import java.util.Scanner;

/** Console menu for the linked-list project. */
public class Main {
    private static final Scanner input = new Scanner(System.in);
    private static final SinglyLinkedList singly = new SinglyLinkedList();
    private static final DoublyLinkedList doubly = new DoublyLinkedList();
    private static final String[] COMPLEXITY = {"O(1) - change the head reference.","O(n) - traverse to the last node; no tail is stored.","O(n) - locate the requested position.","O(n) - locate the first matching node.","O(n) - locate the first matching node.","O(1) - change the head reference.","O(n) - locate the node before the tail.","O(n) - locate the requested node.","O(n) - locate the first matching node.","O(n) - linear search from the head.","O(n) - locate the first matching node.","O(n) - visit and print every node.","O(n) - visit every node.","O(n) - scan all node values.","O(n) - scan all node values.","O(n) - slow and fast pointers find the second middle.","O(n) - visit each node once and relink references.","O(n²) worst case - bubble sort compares adjacent values.","O(n²) - nested traversal removes later duplicates."};
    private static final String[] SINGLY = {"Insert at Beginning","Insert at End","Insert at Position","Insert After a Node","Insert Before a Node","Delete from Beginning","Delete from End","Delete from Position","Delete by Value","Search","Update","Display","Count Nodes","Find Maximum","Find Minimum","Find Middle Element","Reverse","Sort","Remove Duplicates","Exit"};
    private static final String[] DOUBLY = {"Insert at Beginning","Insert at End","Insert at Position","Insert After a Node","Insert Before a Node","Delete from Beginning","Delete from End","Delete from Position","Delete by Value","Search","Update","Display Forward","Display Backward","Count Nodes","Find Maximum","Find Minimum","Find Middle Element","Reverse","Sort","Remove Duplicates","Exit"};
    public static void main(String[] args) {
        while (true) {
            System.out.println("\nLINKED LIST MANAGEMENT SYSTEM\n1. Singly Linked List\n2. Doubly Linked List\n3. Compare Singly vs Doubly Linked List\n4. Exit");
            int choice=readInt("Choose an option: ");
            if(choice==1) singlyMenu(); else if(choice==2) doublyMenu(); else if(choice==3) compare(); else if(choice==4){System.out.println("Goodbye!");return;} else System.out.println("Invalid choice. Select 1 to 4.");
        }
    }
    private static void singlyMenu(){while(true){System.out.println("\nSINGLY LINKED LIST");for(int i=0;i<SINGLY.length;i++)System.out.println((i+1)+". "+SINGLY[i]);int c=readInt("Choose an operation: ");
    if(c==20)return;if(c<1||c>19){System.out.println("Invalid choice.");
    continue;
}
int v,p;
boolean ok;
switch(c){case 1:singly.insertAtBeginning(readInt("Value: "));
break;
case 2:singly.insertAtEnd(readInt("Value: "));
break;
case 3:v=readInt("Value: ");
p=readInt("Position (1-based): ");ok=singly.insertAtPosition(v,p);result(ok,"Inserted.","Invalid position.");break;case 4:v=readInt("Value to insert: ");p=readInt("Insert after value: ");result(singly.insertAfter(p,v),"Inserted.","Target not found.");break;case 5:v=readInt("Value to insert: ");p=readInt("Insert before value: ");result(singly.insertBefore(p,v),"Inserted.","Target not found.");break;case 6:result(singly.deleteFromBeginning(),"Deleted.","List is empty.");break;case 7:result(singly.deleteFromEnd(),"Deleted.","List is empty.");break;case 8:result(singly.deleteAtPosition(readInt("Position: ")),"Deleted.","Invalid position.");break;case 9:result(singly.deleteByValue(readInt("Value: ")),"Deleted first occurrence.","Value not found.");break;case 10:p=singly.search(readInt("Search value: "));System.out.println(p<0?"Value not found.":"Found at position "+p+".");break;case 11:v=readInt("Existing value: ");p=readInt("New value: ");result(singly.update(v,p),"Updated first occurrence.","Value not found.");break;case 12:singly.display();break;case 13:System.out.println("Node count: "+singly.count());break;case 14:printExtreme("Maximum",singly.maximum());break;case 15:printExtreme("Minimum",singly.minimum());break;case 16:printExtreme("Middle",singly.middle());break;case 17:singly.reverse();System.out.println("List reversed.");break;case 18:singly.bubbleSort();System.out.println("List sorted.");break;case 19:singly.removeDuplicates();System.out.println("Duplicate values removed.");break;}showComplexity(c-1,false);}}
    private static void doublyMenu(){while(true){System.out.println("\nDOUBLY LINKED LIST");for(int i=0;i<DOUBLY.length;i++)System.out.println((i+1)+". "+DOUBLY[i]);int c=readInt("Choose an operation: ");if(c==21)return;if(c<1||c>20){System.out.println("Invalid choice.");continue;}int v,p;switch(c){case 1:doubly.insertAtBeginning(readInt("Value: "));break;case 2:doubly.insertAtEnd(readInt("Value: "));break;case 3:v=readInt("Value: ");p=readInt("Position (1-based): ");result(doubly.insertAtPosition(v,p),"Inserted.","Invalid position.");break;case 4:v=readInt("Value to insert: ");p=readInt("Insert after value: ");result(doubly.insertAfter(p,v),"Inserted.","Target not found.");break;case 5:v=readInt("Value to insert: ");p=readInt("Insert before value: ");result(doubly.insertBefore(p,v),"Inserted.","Target not found.");break;case 6:result(doubly.deleteFromBeginning(),"Deleted.","List is empty.");break;case 7:result(doubly.deleteFromEnd(),"Deleted.","List is empty.");break;case 8:result(doubly.deleteAtPosition(readInt("Position: ")),"Deleted.","Invalid position.");break;case 9:result(doubly.deleteByValue(readInt("Value: ")),"Deleted first occurrence.","Value not found.");break;case 10:p=doubly.search(readInt("Search value: "));System.out.println(p<0?"Value not found.":"Found at position "+p+".");break;case 11:v=readInt("Existing value: ");p=readInt("New value: ");result(doubly.update(v,p),"Updated first occurrence.","Value not found.");break;case 12:doubly.displayForward();break;case 13:doubly.displayBackward();break;case 14:System.out.println("Node count: "+doubly.count());break;case 15:printExtreme("Maximum",doubly.maximum());break;case 16:printExtreme("Minimum",doubly.minimum());break;case 17:printExtreme("Middle",doubly.middle());break;case 18:doubly.reverse();System.out.println("List reversed.");break;case 19:doubly.bubbleSort();System.out.println("List sorted.");break;case 20:doubly.removeDuplicates();System.out.println("Duplicate values removed.");break;}showComplexity(c-1,true);}}
        private static void showComplexity(int i,boolean d){String[] dc={"O(1) - update head and its links.","O(1) - maintained tail points to insertion position.","O(n) - traverse to the requested position.","O(n) - find the first matching node.","O(n) - find the first matching node.","O(1) - update head and its links.","O(1) - maintained tail points to the last node.","O(n) - traverse to the requested position.","O(n) - find the first matching node.","O(n) - linear search.","O(n) - find the first matching node.","O(n) - traverse and print forward.","O(n) - traverse and print backward.","O(n) - visit every node.","O(n) - scan node values.","O(n) - scan node values.","O(n) - slow and fast pointers locate the second middle.","O(n) - swap links once per node.","O(n²) worst case - bubble sort compares adjacent values.","O(n²) - nested traversal removes later duplicates."};System.out.println("Expected time complexity: "+(d?dc[i]:COMPLEXITY[i]));}
    private static int readInt(String prompt){while(true){System.out.print(prompt);String line=input.nextLine().trim();try{return Integer.parseInt(line);}catch(NumberFormatException e){System.out.println("Enter a valid integer.");}}}
    private static void result(boolean ok,String yes,String no){System.out.println(ok?yes:no);}
    private static void printExtreme(String label,Integer value){System.out.println(value==null?"List is empty.":label+": "+value);}
    private static void compare(){System.out.println("\nSingly list: each node stores data and next; traversal moves forward only.\nDoubly list: each node stores data, prev and next; traversal moves both ways and uses extra memory per node.\nSingly end insertion is O(n) because it has no tail reference. Doubly end insertion is O(1) because it maintains a tail.\nSearching, counting, display, extrema, and middle are O(n) in both. Bubble sort and nested duplicate removal are O(n²) worst case.");}
}